using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Accounts.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Accounts.Commands.UpdateAccount;public sealed class UpdateAccountCommandHandler(IAccountRepository repository,IApplicationDbContext db):IRequestHandler<UpdateAccountCommand,Result<AccountDto>>{public async Task<Result<AccountDto>>Handle(UpdateAccountCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<AccountDto>(AccountErrors.NotFound);e.Update(request.AccountName,request.AccountType,request.IsPostingAllowed,request.Description);e.MoveUnder(request.ParentAccountId);await db.SaveChangesAsync(cancellationToken);return Result.Success(AccountDto.FromEntity(e));}}
